/// `modes.md`, line 10.
#[rustfmt::skip]
#[test]
fn modes_snippet_1() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::policy::{Capabilities, Mode, Policy, Request};
    let plan = Policy::up_to(Mode::Interactive)
        .resolve(Request::mode(Mode::Interactive), Capabilities::terminal())
        .expect("a terminal can host prompts");
    assert_eq!(plan.mode(), Mode::Interactive);
    // A request the application does not allow is refused, not silently downgraded.
    let refused = Policy::up_to(Mode::Interactive)
        .resolve(Request::mode(Mode::Tui), Capabilities::terminal_with_tui());
    assert!(refused.is_err());
}

/// `modes.md`, line 68.
#[rustfmt::skip]
#[test]
fn modes_snippet_2() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::contract::ExitPolicy;
    use clifacet::{Failure, FailureKind};
    let policy = ExitPolicy::standard();
    assert_eq!(policy.for_kind(FailureKind::Validation), policy.validation());
    assert_eq!(policy.for_failure(&Failure::cancelled("changed their mind")), policy.cancelled());
    assert_eq!(policy.success(), 0);
    assert_eq!(policy.cancelled(), 130);
}

/// `tui-composition.md`, line 21.
#[rustfmt::skip]
#[test]
fn tui_composition_snippet_1() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clap::Parser;
    use clifacet::tui::FormState;
    use clifacet::Facet;
    #[derive(Debug, Parser, Facet)]
    #[facet(input = Input, bridge = build_input)]
    struct Cli {
        /// Who to greet.
        #[arg(long, default_value = "world")]
        name: String,
        /// How many times to greet.
        #[arg(long, default_value_t = 1)]
        repeat: u8,
    }
    #[derive(Debug)]
    struct Input {
        name: String,
        repeat: u8,
    }
    fn build_input(cli: Cli) -> Result<Input, clifacet::Failure> {
        Ok(Input { name: cli.name.clone(), repeat: cli.repeat })
    }
    let state = FormState::generated(&Cli::command(), &["name", "repeat"])
        .expect("the command has both arguments");
    assert_eq!(state.fields().len(), 2);
}

/// `tui-composition.md`, line 61.
#[rustfmt::skip]
#[test]
fn tui_composition_snippet_2() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::tui::ratatui::buffer::Buffer;
    use clifacet::tui::ratatui::layout::Rect;
    use clifacet::tui::ratatui::widgets::{Paragraph, Widget};
    use clifacet::tui::{CustomField, FieldState};
    /// One field, drawn by the application: the value is masked.
    struct Masked;
    impl CustomField for Masked {
        fn draw(&self, field: &FieldState, focused: bool, area: Rect, buffer: &mut Buffer) {
            let marker = if focused { "> " } else { "  " };
            let hidden = "*".repeat(field.value().chars().count());
            Paragraph::new(format!("{marker}{}: {hidden}", field.label())).render(area, buffer);
        }
    }
    let _hatch = Masked;
}

/// `tui-composition.md`, line 101.
#[rustfmt::skip]
#[test]
fn tui_composition_snippet_3() {
    #![allow(unused_variables, unused_imports, dead_code, path_statements)]
    use clifacet::tui::ratatui::backend::TestBackend;
    use clifacet::tui::ratatui::Terminal;
    use clifacet::tui::{FormState, Key};
    let state = FormState::new(vec![clifacet::tui::FieldState::new("name", "Who?", "world")]);
    let keys = [Key::Enter];
    let mut terminal = Terminal::new(TestBackend::new(60, 10)).expect("a test screen");
    let outcome = clifacet::tui::app::run_with(
        &mut terminal,
        &mut state.clone(),
        keys,
        clifacet::tui::draw_form,
        |_state| Ok(vec![String::from("hello, world")]),
    );
    assert!(outcome.is_ok(), "the form submits the answer it was given");
}
